        _safeT(key) {
            try {
                if (window.mySimulation && window.mySimulation.t) {
                    return window.mySimulation.t(key);
                }
            } catch(e) {}
            return key;
        }

        _updateBriefing(state) {
            var period = Math.min(state.currentPeriod || 1, 4);
            var briefEl = document.getElementById('briefingPanel');
            var controlsEl = document.getElementById('controlsPanel');
            var phaseEl = document.getElementById('phaseNameDisplay');

            if (!briefEl || !controlsEl) return;
            this._renderedPeriod = period;

            var t = this._safeT.bind(this);

            if (phaseEl) phaseEl.textContent = t(this.PHASE_KEYS[period - 1]);

            if (period === 1) {
                briefEl.innerHTML = '<h4>' + t('r1_title') + '</h4><p>' + t('r1_briefing') + '</p>';
                controlsEl.innerHTML = this._buildRound1(t);
            } else if (period === 2) {
                briefEl.innerHTML = '<h4>' + t('r2_title') + '</h4><p>' + t('r2_briefing') + '</p>';
                controlsEl.innerHTML = this._buildRound2(t);
            } else if (period === 3) {
                briefEl.innerHTML = '<h4>' + t('r3_title') + '</h4><p>' + t('r3_briefing') + '</p>';
                controlsEl.innerHTML = this._buildRound3(t);
            } else if (period === 4) {
                var dsx = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || state.domainState || {};
                var outcome = dsx.discontinued === true ? t('r4_outcome_dropped') : dsx.discontinued === false ? t('r4_outcome_kept') : '';
                briefEl.innerHTML = '<h4>' + t('r4_title') + '</h4>' + (outcome ? '<p class="profitability-sim-outcome">' + outcome + '</p>' : '') + '<p>' + t('r4_briefing') + '</p>';
                controlsEl.innerHTML = this._buildRound4(t);
            }
        }

        _buildRound1(t) {
            var h = '<table class="table table-sm table-bordered"><thead><tr>';
            h += '<th>#</th><th>' + t('cost_item_col') + '</th><th>' + t('classification_col') + '</th>';
            h += '</tr></thead><tbody>';
            for (var i = 1; i <= 10; i++) {
                h += '<tr><td>' + i + '</td>';
                h += '<td id="costLbl' + i + '">' + t('cost_' + i) + '</td>';
                h += '<td><select id="cost' + i + '" class="form-control form-control-sm" aria-labelledby="costLbl' + i + '">';
                h += '<option value="">' + t('select_option') + '</option>';
                h += '<option value="F">' + t('fixed') + '</option>';
                h += '<option value="V">' + t('variable') + '</option>';
                h += '</select></td></tr>';
            }
            h += '</tbody></table>';
            return h;
        }

        _buildRound2(t) {
            var h = '<table class="table table-sm table-bordered"><thead><tr>';
            h += '<th>' + t('product_col') + '</th>';
            h += '<th>' + t('price_col') + '</th>';
            h += '<th>' + t('variable_cost_col') + '</th>';
            h += '<th>' + t('volume_col') + '</th>';
            h += '<th>' + t('cm_input_col') + '</th>';
            h += '</tr></thead><tbody>';

            // the margin cannot exceed the price: min 0, max the price, any decimal (so a ratio typed by mistake is still accepted and scored)
            h += '<tr><td id="prodLblFlyers">' + t('flyers') + '</td><td>2.800</td><td>2.180</td><td>140</td>';
            h += '<td><input type="number" id="cmFlyers" class="form-control form-control-sm" aria-labelledby="prodLblFlyers" placeholder="$UY" min="0" max="2800" step="any" inputmode="decimal"></td></tr>';

            h += '<tr><td id="prodLblBrochures">' + t('brochures') + '</td><td>4.600</td><td>2.900</td><td>85</td>';
            h += '<td><input type="number" id="cmBrochures" class="form-control form-control-sm" aria-labelledby="prodLblBrochures" placeholder="$UY" min="0" max="4600" step="any" inputmode="decimal"></td></tr>';

            h += '<tr><td id="prodLblLargeFormat">' + t('large_format') + '</td><td>14.500</td><td>5.650</td><td>22</td>';
            h += '<td><input type="number" id="cmLargeFormat" class="form-control form-control-sm" aria-labelledby="prodLblLargeFormat" placeholder="$UY" min="0" max="14500" step="any" inputmode="decimal"></td></tr>';

            h += '</tbody></table>';

            h += '<div class="profitability-sim-ranking-section">';
            h += '<h5>' + t('ranking_heading') + '</h5>';
            h += '<p>' + t('ranking_instruction') + '</p>';

            var opts = '<option value="">' + t('select_option') + '</option>';
            opts += '<option value="flyers">' + t('flyers') + '</option>';
            opts += '<option value="brochures">' + t('brochures') + '</option>';
            opts += '<option value="largeFormat">' + t('large_format') + '</option>';

            h += '<div class="profitability-sim-rank-row"><label for="ranking1">' + t('rank_1') + ':</label>';
            h += '<select id="ranking1" class="form-control form-control-sm">' + opts + '</select></div>';
            h += '<div class="profitability-sim-rank-row"><label for="ranking2">' + t('rank_2') + ':</label>';
            h += '<select id="ranking2" class="form-control form-control-sm">' + opts + '</select></div>';
